CREATE TABLE entitlement_defaults(id TEXT PRIMARY KEY CHECK(id IN ('standard','demo')),limits_json TEXT NOT NULL,updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL);
INSERT INTO entitlement_defaults VALUES('standard','{"projects":1000,"seats":20,"brands":100,"characters":100,"apiKeys":20,"concurrency":2,"textAssistDailyFreeUnits":0}',NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO entitlement_defaults VALUES('demo','{"projects":1000,"seats":20,"brands":100,"characters":100,"apiKeys":20,"concurrency":2,"textAssistDailyFreeUnits":0}',NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE free_text_claims(item_id TEXT PRIMARY KEY REFERENCES job_items(id),job_id TEXT NOT NULL REFERENCES jobs(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),period_day TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX free_text_claims_period ON free_text_claims(workspace_id,period_day);
CREATE TABLE support_resolutions(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL UNIQUE REFERENCES support_tickets(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')),reason TEXT NOT NULL,evidence_reference TEXT NOT NULL,actor_user_id TEXT NOT NULL REFERENCES users(id),request_hash TEXT NOT NULL,refunded_credits INTEGER NOT NULL CHECK(refunded_credits>=0),created_at TEXT NOT NULL);
CREATE TABLE support_refunds(id TEXT PRIMARY KEY,resolution_id TEXT NOT NULL REFERENCES support_resolutions(id),item_id TEXT NOT NULL UNIQUE REFERENCES job_items(id),job_id TEXT NOT NULL REFERENCES jobs(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),credits INTEGER NOT NULL CHECK(credits>0),created_at TEXT NOT NULL);
